mapper.select:
	select
	group_concat(ed.trader ORDER BY ed.create_time separator ',') trader
	from ETR_DISTRIBUTE ed left join ETR_ENTRUST ee on ed.entrust_id = ee.entrust_id


			and ed.entrust_id = #{entrustId}


			and ee.FINPROD_ID = #{finprodId}


			and DATE_FORMAT(ed.update_time,'%Y-%m-%d')=#{entrustDate}



				and ed.REC_STATUS = #{entrustStatus}


				and ed.REC_STATUS ! = #{entrustStatusBack}



	group by ed.entrust_id,ee.create_time
 order by ee.create_time desc

select group_concat(aa.USER_IDr ORDER BY aa.SEQ,aa.num separator ',') trader
from ETR_DISTRIBUTE ed
 inner join ETR_ENTRUST ee on ed.entrust_id = ee.entrust_id
 inner join
	(select ts.SEQ, ts.USER_ID, count(1) num
	from TRADOR_SEQ ts
	inner join ETR_DISTRIBUTE ed on ed.TRADER = ts.USER_ID
	inner join ETR_ENTRUST ee on ed.entrust_id = ee.entrust_id


			and ed.entrust_id = #{entrustId}


			and ee.FINPROD_ID = #{finprodId}


			and DATE_FORMAT(ed.update_time,'%Y-%m-%d')=#{entrustDate}



				and ed.REC_STATUS = #{entrustStatus}


				and ed.REC_STATUS ! = #{entrustStatusBack}



	group by ts.USER_ID,ts.SEQ
	order by ts.SEQ,num) aa on aa.USER_ID = ed.trader


		and ed.entrust_id = #{entrustId}


		and ee.FINPROD_ID = #{finprodId}


		and DATE_FORMAT(ed.update_time,'%Y-%m-%d')=#{entrustDate}



			and ed.REC_STATUS = #{entrustStatus}


			and ed.REC_STATUS ! = #{entrustStatusBack}



group by ed.entrust_id,ee.create_time
order by ee.create_time desc
